import std.io

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    var k: Int64 = 3
    let a = 12 & 10
    let b = 12 | 3
    let c = 12 ^ 5
    let lo = 1 << k
    let r = 256 >> k
    let neg = 0 - 8
    let asr = neg >> 1
    if a == 8 { io.println("and-ok") } else { io.println("and-bad") }
    if b == 15 { io.println("or-ok") } else { io.println("or-bad") }
    if c == 9 { io.println("xor-ok") } else { io.println("xor-bad") }
    if lo == 8 { io.println("shl-ok") } else { io.println("shl-bad") }
    if r == 32 { io.println("shr-ok") } else { io.println("shr-bad") }
    if asr == 0 - 4 { io.println("ashr-ok") } else { io.println("ashr-bad") }
    return Ok(())
}
